    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: "Lobar consolidation" is the classic radiographic presentation of which type of pneumonia?', '["Viral pneumonia", "Streptococcus pneumoniae (Pneumococcal)", "Mycoplasma pneumonia", "Pneumocystis jirovecii"]', 1, 'Pneumococcal pneumonia typically causes dense consolidation involving an entire lobe, often with air bronchograms.'),
    (v_topic_id, '102: "Interstitial" (or patchy) infiltrates are more common in which type of lung infection?', '["Lobar pneumonia", "Atypical/Viral pneumonia", "Lung abscess", "Staphylococcal pneumonia"]', 1, 'Atypical pathogens (like Mycoplasma) and viruses often cause fine, diffuse interstitial markings rather than solid consolidation.'),
    (v_topic_id, '103: A "Round Pneumonia" is a radiographic curiosity where a consolidation appears as a spherical mass. It is most commonly seen in which population?', '["Elderly smokers", "Children", "Pregnant women", "Athletes"]', 1, 'In children, the pores of Kohn are poorly developed, allowing pneumonia to present as a discrete round mass that can mimic a tumor.'),
    (v_topic_id, '104: "Aspiration Pneumonia" most commonly involves which part of the lungs in a recumbent (lying down) patient?', '["Apical segments of the upper lobes", "Superior segments of the lower lobes or posterior segments of the upper lobes", "Anterior segments of the upper lobes", "Bases of the lower lobes"]', 1, 'Gravity directs aspirated material to these dependent areas when a patient is supine.'),
    (v_topic_id, '105: If an upright patient aspirates, where is the most likely location for the resulting pneumonia?', '["Left upper lobe", "Right lower lobe (basal segments)", "Left lower lobe", "Right upper lobe"]', 1, 'The right mainstem bronchus is straighter, wider, and more vertical than the left, making the right lower lobe the most common site.'),
    (v_topic_id, '106: "Klebsiella pneumoniae" is classically associated with which specific radiographic finding?', '["The \"Bulging Fissure\" sign", "Pleural effusion", "Small nodules", "Hilar lymphadenopathy"]', 0, 'Klebsiella causes a heavy, voluminous inflammatory exudate that can cause the adjacent fissure to bulge downward.'),
    (v_topic_id, '107: A "Lung Abscess" is distinguished from simple pneumonia on CXR by the presence of:', '["A thick-walled cavity with an air-fluid level", "A thin-walled cyst", "Diffuse infiltrates", "Low lung volumes"]', 0, 'Abscesses represent localized tissue necrosis and liquefaction.'),
    (v_topic_id, '108: Which of the following is a "Direct Sign" of lung volume loss (atelectasis)?', '["Displacement of the mediastinum", "Elevation of the diaphragm", "Displacement of an interlobar fissure", "Crowding of the ribs"]', 2, 'Fissural displacement is the only direct sign; the others are indirect signs of compensation.'),
    (v_topic_id, '109: "Resorptive" (Obstructive) atelectasis is caused by:', '["Compression by a large pleural effusion", "Complete obstruction of an airway (e.g., by a tumor or mucus plug)", "Loss of surfactant", "Scarring of the lung"]', 1, 'Air distal to the obstruction is absorbed into the bloodstream, leading to collapse.'),
    (v_topic_id, '110: "Passive" (Compression) atelectasis is caused by:', '["A mass within the bronchus", "External pressure on the lung from a pleural effusion or pneumothorax", "Cystic fibrosis", "General anesthesia"]', 1, 'The lung collapses simply because something else is taking up space in the chest.'),
    (v_topic_id, '111: A "Spiculated" pulmonary nodule has a high probability of being:', '["A benign hamartoma", "Bronchogenic carcinoma", "A healed granuloma", "An arteriovenous malformation"]', 1, 'Spiculation represents malignant cells invading the surrounding interstitial tissue.'),
    (v_topic_id, '112: The "Fleischner Society" guidelines are used for:', '["Diagnosing pneumonia", "Management of incidentally detected pulmonary nodules", "Treating pleural effusions", "Evaluating heart failure"]', 1, 'These guidelines dictate the frequency of follow-up CT scans based on nodule size and patient risk factors.'),
    (v_topic_id, '113: Which calcification pattern in a lung nodule is considered "Benign"?', '["Central, diffuse, or laminated", "Eccentric", "Stippled", "None of the above"]', 0, 'Benign nodules (like granulomas) often have solid, central, or concentric "target" calcification.'),
    (v_topic_id, '114: A nodule that has remained stable in size for how long is generally considered benign?', '["6 months", "1 year", "2 years", "5 years"]', 2, 'Stability over 2 years is a strong indicator of a benign process, although some slow-growing cancers (like carcinoid) can be exceptions.'),
    (v_topic_id, '115: "Pulmonary Edema" typically progresses through which stages on CXR?', '["Hilar congestion -> Interstitial edema (Kerley lines) -> Alveolar edema (Bat-wing)", "Bat-wing -> Kerley lines -> Pleural effusion", "Atelectasis -> Consolidation -> Cavitation", "Normal -> Pneumothorax -> Edema"]', 0, 'As pulmonary venous pressure rises, fluid moves from vessels to interstitium and finally into the alveoli.'),
    (v_topic_id, '116: "Non-cardiogenic" pulmonary edema (e.g., ARDS) is distinguished from cardiogenic edema by:', '["Lack of cardiomegaly and lack of pleural effusions", "Presence of Kerley B lines", "Cephalization of vessels", "A Bat-wing pattern"]', 0, 'In ARDS, the heart is usually normal size and the distribution of edema can be more patchy.'),
    (v_topic_id, '117: What is the most common cause of a "Unilateral" hyperlucent (extra black) lung?', '["Pneumothorax", "Mastectomy (loss of soft tissue)", "Swyer-James syndrome", "All of the above"]', 3, 'Loss of soft tissue, lung volume, or vascularity can all make one lung look darker than the other.'),
    (v_topic_id, '118: "Bronchiectasis" is best diagnosed with which imaging modality?', '["Standard CXR", "High-Resolution CT (HRCT)", "MRI", "Nuclear V/Q scan"]', 1, 'HRCT can visualize the dilated, thick-walled bronchi that CXR often misses.'),
    (v_topic_id, '119: The "Signet Ring Sign" on CT is the hallmark of:', '["Lung cancer", "Bronchiectasis", "Pulmonary embolism", "Atelectasis"]', 1, 'This occurs when a dilated bronchus is larger than its accompanying pulmonary artery.'),
    (v_topic_id, '120: "Tree-in-bud" opacities on CT represent:', '["Early lung cancer", "Endobronchial spread of infection (e.g., TB or bacterial pneumonia)", "Pulmonary edema", "Pulmonary fibrosis"]', 1, 'This pattern reflects impaction of small airways with mucus, pus, or fluid.'),
    (v_topic_id, '121: In "Cystic Fibrosis," the radiographic changes (bronchiectasis, mucus plugging) are usually most severe in which part of the lungs?', '["Upper lobes", "Lower lobes", "Bases only", "Hilar region"]', 0, 'Unlike many other forms of bronchiectasis, CF typically involves the upper lobes most prominently.'),
    (v_topic_id, '122: "Septic Pulmonary Emboli" appear on CXR as:', '["Single large mass", "Multiple, peripheral, poorly defined nodules that may cavitate", "Diffuse ground-glass", "Pleural effusion only"]', 1, 'These result from infected material (e.g., from tricuspid endocarditis) seeding the lungs via the bloodstream.'),
    (v_topic_id, '123: "Septal thickening" (Kerley B lines) can be caused by conditions other than heart failure, such as:', '["Lymphangitic carcinomatosis", "Sarcoidosis", "Silicosis", "All of the above"]', 3, 'Anything that infiltrates the interlobular septa (fluid, cells, or fiber) will create these lines.'),
    (v_topic_id, '124: "Fleischner''s Line" is a synonym for:', '["A rib fracture", "Discoid (platelike) atelectasis", "A pleural plaque", "A pulmonary artery"]', 1, 'These are common, thin horizontal lines at the lung bases.'),
    (v_topic_id, '125: "Pneumatocele" is a thin-walled, air-filled cyst within the lung, most commonly occurring after which infection?', '["Mycoplasma", "Staphylococcal pneumonia", "Tuberculosis", "Viral flu"]', 1, 'Staph aureus and sometimes Coccidioidomycosis are classic causes.'),
    (v_topic_id, '126: "Pneumocystis jirovecii" pneumonia (PCP) in HIV patients classically presents as:', '["Lobar consolidation", "Diffuse, perihilar ground-glass opacities", "Large cavitary lesions", "Pleural effusions"]', 1, 'PCP characteristically spares the lung periphery and does not typically cause effusions.'),
    (v_topic_id, '127: A "Cannonball" appearance (multiple large, well-defined nodules) is highly suggestive of:', '["Primary lung cancer", "Metastatic disease (e.g., renal cell, choriocarcinoma)", "Pneumonia", "Tuberculosis"]', 1, 'The lungs are a common site for hematogenous spread of various cancers.'),
    (v_topic_id, '128: "Aspergilloma" (a fungus ball) is most commonly found within:', '["Normal lung tissue", "A pre-existing lung cavity (e.g., from old TB or sarcoidosis)", "The pleural space", "The hila"]', 1, 'The fungus colonizes a "dead space" within the lung.'),
    (v_topic_id, '129: The "Monod Sign" or "Air Crescent Sign" refers to air surrounding a:', '["Lung cancer", "Mycetoma (fungus ball)", "Pneumothorax", "Blood clot"]', 1, 'Air between the fungus ball and the wall of the cavity creates a crescent shape.'),
    (v_topic_id, '130: In "Silicosis," the nodules are most common in the:', '["Lower lobes", "Upper lobes", "Mediastinum", "Pleura"]', 1, 'Inhaled inorganic dusts like silica and coal typically affect the upper lobes.'),
    (v_topic_id, '131: "Asbestosis" is a form of interstitial fibrosis that characteristically affects the:', '["Upper lobes", "Lower lobes", "Perihilar region", "Apex"]', 1, 'Asbestos is an exception to the "dust in the upper lobes" rule; it involves the bases.'),
    (v_topic_id, '132: "Coal Worker''s Pneumoconiosis" (CWP) can progress to "Progressive Massive Fibrosis" (PMF), which looks like:', '["Large, dense masses in the upper lobes", "Pneumothorax", "Pleural effusions", "Cavitary lesions"]', 0, 'Small nodules coalesce into large, conglomerate masses of fibrous tissue.'),
    (v_topic_id, '133: "Caplan Syndrome" is the combination of pneumoconiosis (like silicosis) and:', '["Systemic Lupus Erythematosus", "Rheumatoid Arthritis (with pulmonary nodules)", "Scleroderma", "Sarcoidosis"]', 1, 'The rheumatoid nodules are often large and may cavitate.'),
    (v_topic_id, '134: A "Solitary Pulmonary Nodule" (SPN) with "eccentric" calcification is:', '["Definitely benign", "Highly suspicious for malignancy (as a tumor may engulf a small granuloma)", "Diagnostic of TB", "A normal variant"]', 1, 'Any non-central/non-diffuse calcification is worrisome.'),
    (v_topic_id, '135: "Bronchioloalveolar Carcinoma" (now called Lepidic Adenocarcinoma) can uniquely mimic:', '["A simple cyst", "Localized or diffuse pneumonia (consolidation)", "A pleural effusion", "A pneumothorax"]', 1, 'It can spread along the alveolar walls without destroying the lung architecture.'),
    (v_topic_id, '136: Which of the following is an "Indirect Sign" of atelectasis?', '["Elevation of the hemidiaphragm", "Mediastinal shift toward the collapse", "Compensatory hyperinflation of the remaining lung", "All of the above"]', 3, 'These are all changes the body makes to fill the space left by the collapsed lung.'),
    (v_topic_id, '137: "Right Middle Lobe Syndrome" refers to recurrent or chronic atelectasis of the RML, often due to:', '["The long, narrow, and easily compressed nature of the RML bronchus", "Smoking", "Heart failure", "Asthma"]', 0, 'The RML bronchus is surrounded by lymph nodes that can compress it when enlarged.'),
    (v_topic_id, '138: On a PA film, "Right Lower Lobe" consolidation will silhouette (obscure) the:', '["Right heart border", "Right hemidiaphragm", "Aorta", "Hila"]', 1, 'The lower lobes rest on the diaphragm but are posterior to the heart.'),
    (v_topic_id, '139: On a PA film, "Left Lower Lobe" consolidation will silhouette the:', '["Left heart border", "Left hemidiaphragm", "Trachea", "Clavicle"]', 1, 'The LLL is posterior to the heart; loss of the diaphragm border is the key finding.'),
    (v_topic_id, '140: "Juxtaphrenic Peak" is a small triangular opacity at the peak of the diaphragm seen in:', '["Pneumonia", "Upper lobe atelectasis", "Pleural effusion", "Liver disease"]', 1, 'It is an indirect sign of upper lobe volume loss.'),
    (v_topic_id, '141: A "Perihilar" opacity is located:', '["At the lung bases", "Near the roots (hila) of the lungs", "In the apices", "Against the chest wall"]', 1, 'This is a common location for edema or lymphadenopathy.'),
    (v_topic_id, '142: In "Active Primary Tuberculosis," the most common radiographic finding in a child is:', '["Apical cavitation", "Hilar or paratracheal lymphadenopathy", "Pleural plaques", "Rib destruction"]', 1, 'Primary TB often presents with lymph node enlargement rather than the classic apical cavitary disease of reactivation.'),
    (v_topic_id, '143: A "Ghon Complex" consists of:', '["A calcified lung nodule + a calcified hilar lymph node", "A large cavity", "A pleural effusion + pneumonia", "Two lung nodules"]', 0, 'This is the healed state of a primary TB infection.'),
    (v_topic_id, '144: "Ranke Complex" is another name for a:', '["New TB infection", "Healed, calcified Ghon complex", "Active pneumonia", "Lung abscess"]', 1, 'It is a late radiographic sign of old TB.'),
    (v_topic_id, '145: "Reactivation Tuberculosis" classically involves which part of the lungs?', '["Bases", "Middle lobe", "Apical and posterior segments of the upper lobes", "Pleural space only"]', 2, 'TB bacteria thrive in these highly oxygenated areas of the lung.'),
    (v_topic_id, '146: "Miliary Tuberculosis" results from:', '["Localized spread", "Hematogenous (blood-borne) dissemination", "Lymphatic spread only", "Direct contact with the skin"]', 1, 'Bacteria spread throughout the body, seeding the lungs with tiny nodules.'),
    (v_topic_id, '147: Which of the following is the most sensitive test for detecting "Active Tuberculosis"?', '["CXR", "Sputum Culture/NAAT", "MRI", "Ultrasound"]', 1, 'CXR can be suggestive, but definitive diagnosis requires microbiological proof.'),
    (v_topic_id, '148: "Hamman Sign" is a crunching sound heard over the heart during systole, indicative of:', '["Pericarditis", "Pneumomediastinum (air in the mediastinum)", "Pneumothorax", "Aortic stenosis"]', 1, 'Air around the heart is "crunched" by the cardiac motion.'),
    (v_topic_id, '149: "Pneumomediastinum" appears on CXR as:', '["A thick white mass", "Thin streaks of air outlining the heart and great vessels", "Lung collapse", "Blunting of the angles"]', 1, 'Air tracks along the tissue planes of the mediastinum.'),
    (v_topic_id, '150: The "Continuous Diaphragm Sign" is a sign of:', '["Pneumothorax", "Pneumomediastinum", "Pneumoperitoneum", "Lung consolidation"]', 1, 'Air trapped between the heart and the diaphragm allows the entire diaphragm border to be seen.'),
    (v_topic_id, '151: "Spinnaker Sail Sign" in an infant is a sign of:', '["Thymic enlargement", "Pneumomediastinum (air lifting the thymus)", "Pneumothorax", "Congenital heart disease"]', 1, 'Air in the mediastinum lifts the lobes of the thymus up and out.'),
    (v_topic_id, '152: "Subcutaneous Emphysema" appears on CXR as:', '["Dense white soft tissue", "Air bubbles or streaks within the soft tissues of the neck or chest wall", "Lung nodules", "Rib thickening"]', 1, 'This often looks like "feathers" or black streaks in the skin/muscle areas.'),
    (v_topic_id, '153: If you see "Subcutaneous Emphysema," you must look carefully for an underlying:', '["Pneumothorax or Pneumomediastinum", "Pneumonia", "Lung cancer", "Heart failure"]', 0, 'Air usually escapes from the lung or airway into the soft tissues.'),
    (v_topic_id, '154: "Sarcoidosis" Stage 2 involves:', '["Hilar lymphadenopathy only", "Hilar lymphadenopathy + parenchymal lung disease", "Parenchymal disease only", "Pulmonary fibrosis"]', 1, 'Stage 2 is a combination of both nodes and lung involvement.'),
    (v_topic_id, '155: "L\u00f6fgren Syndrome" is an acute form of sarcoidosis consisting of:', '["Bilateral hilar lymphadenopathy, erythema nodosum, and polyarthritis", "Lung cancer and fever", "TB and weight loss", "Heart failure and edema"]', 0, 'This syndrome has a very good prognosis.'),
    (v_topic_id, '156: "Hilar Lymphadenopathy" that is UNILATERAL should always raise suspicion for:', '["Sarcoidosis", "Primary lung cancer or Lymphoma", "Congestive heart failure", "Normal variant"]', 1, 'Sarcoid is classically bilateral; unilateral enlargement is more worrisome for malignancy.'),
    (v_topic_id, '157: "Broncholith" is a calcified lymph node that has eroded into a:', '["Vessel", "Bronchus", "Pleura", "Skin"]', 1, 'This can cause coughing up of small "stones" and localized atelectasis.'),
    (v_topic_id, '158: "Invasive Pulmonary Aspergillosis" is most common in:', '["Healthy young adults", "Severely immunocompromised patients (e.g., post-transplant)", "Asthmatics", "The elderly"]', 1, 'The fungus invades tissue and vessels rather than just sitting in a cavity.'),
    (v_topic_id, '159: "Allergic Bronchopulmonary Aspergillosis" (ABPA) typically presents with:', '["Large cavities", "Finger-in-glove opacities (mucus impaction in dilated bronchi)", "Pneumothorax", "Rib fractures"]', 1, 'This is a hypersensitivity reaction common in asthmatics and CF patients.'),
    (v_topic_id, '160: "Fleischner''s Sign" in PE refers to:', '["A wedge-shaped infarct", "A prominent, enlarged central pulmonary artery", "Oligemia", "Pleural effusion"]', 1, 'The artery is distended by the large clot within it.'),
    (v_topic_id, '161: "Interlobular septa" are the boundaries of the:', '["Secondary pulmonary lobules", "Primary alveoli", "Lobes", "Bronchial segments"]', 0, 'These are the smallest functional units of the lung visible on CT.'),
    (v_topic_id, '162: "Centrilobular" emphysema is most commonly associated with:', '["Alpha-1 antitrypsin deficiency", "Smoking", "Asbestosis", "Sarcoidosis"]', 1, 'Smoking-related damage starts in the center of the lobule in the upper lobes.'),
    (v_topic_id, '163: "Panacinar" emphysema is the hallmark of:', '["Smoking", "Alpha-1 antitrypsin deficiency", "Old age", "Asthma"]', 1, 'Damage involves the entire lobule and is more prominent at the lung bases.'),
    (v_topic_id, '164: "Bullous Emphysema" involves large air-filled spaces (bullae) that measure at least:', '["5 mm", "1 cm", "3 cm", "5 cm"]', 1, 'Bullae can rupture, causing a spontaneous pneumothorax.'),
    (v_topic_id, '165: "Vanishing Lung Syndrome" is characterized by:', '["Lung cancer", "Large bullae occupying at least one-third of a hemithorax", "Atelectasis", "Agenesis of the lung"]', 1, 'This is an extreme form of bullous emphysema, usually in young smokers.'),
    (v_topic_id, '166: "Crazy Paving" pattern on HRCT (ground-glass with superimposed septal thickening) is classic for:', '["Pulmonary Alveolar Proteinosis", "Heart failure", "ARDS", "All of the above"]', 3, 'While classic for Alveolar Proteinosis, it is a non-specific sign of many acute processes.'),
    (v_topic_id, '167: "Reverse Bat-wing" (peripheral) consolidation is the hallmark of:', '["Heart failure", "Chronic Eosinophilic Pneumonia", "Lobar pneumonia", "Lung cancer"]', 1, 'The opacities are "photonegative" of the central bat-wing of heart failure.'),
    (v_topic_id, '168: "Amiodarone Toxicity" can cause which lung finding on CT?', '["Pleural effusion", "Hyperdense (bright) pulmonary infiltrates or liver", "Lung nodules", "Pneumothorax"]', 1, 'Amiodarone contains iodine, which makes the affected tissue appear denser (brighter) on CT.'),
    (v_topic_id, '169: "Pleural effusion" on a supine film appears as:', '["A sharp meniscus", "A hazy increase in density over the entire hemithorax (veil-like opacity)", "A black hole", "Blunting of the angle"]', 1, 'Since the fluid layers posteriorly, it increases the overall density of the lung field.'),
    (v_topic_id, '170: "Pneumothorax" on a supine film is often difficult to see. Where should you look?', '["In the apices", "At the bases and costophrenic angles (deep sulcus sign)", "Against the spine", "In the hila"]', 1, 'Air rises to the highest (anterior/inferior) point in a supine patient.'),
    (v_topic_id, '171: "Pseudo-pneumothorax" is a common artifact caused by:', '["A skin fold", "A rib", "The edge of a pillow", "Hair"]', 0, 'A skin fold creates a dark line that can be mistaken for a pleural line, but it usually crosses the lung edge.'),
    (v_topic_id, '172: How do you distinguish a "Skin Fold" from a true "Pneumothorax" line?', '["Skin folds are thicker and often have lung markings visible beyond them", "Pneumothorax is always on the left", "Skin folds are white", "There is no way to tell"]', 0, 'A true pneumothorax line will have no vascular markings distal to it.'),
    (v_topic_id, '173: "Pleural calcification" that follows the contours of the ribs is called:', '["Plaque", "Fibrothorax", "Pleural effusion", "Atelectasis"]', 1, 'This is usually the result of an old hemothorax or empyema (calcified pleura).'),
    (v_topic_id, '174: A "Pleural-based" mass is typically characterized by:', '["Acute angles with the chest wall", "Obtuse (wide) angles with the chest wall", "Air bronchograms", "Movement with respiration"]', 1, 'This helps distinguish a mass arising from the pleura/wall from one within the lung parenchyma.'),
    (v_topic_id, '175: "Mesothelioma" (malignant tumor of the pleura) typically presents as:', '["A single lung nodule", "Nodular, circumferential pleural thickening", "Blunting of the angles only", "A cavitary lesion"]', 1, 'This "pleural rind" is highly characteristic of mesothelioma.'),
    (v_topic_id, '176: "Pleural Effusion" that does not move on a decubitus film is:', '["Simple", "Loculated (trapped)", "Normal", "Insignificant"]', 1, 'Loculation suggests an underlying inflammatory process like empyema or malignancy.'),
    (v_topic_id, '177: "Empyema" is defined as:', '["Pus in the pleural space", "Blood in the pleural space", "Air in the pleural space", "Water in the pleural space"]', 0, 'Radiographically, it often looks like a lens-shaped (lenticular) loculated effusion.'),
    (v_topic_id, '178: "Split Pleura Sign" on contrast CT is diagnostic for:', '["Pneumothorax", "Empyema", "Simple effusion", "Lung cancer"]', 1, 'The visceral and parietal pleura both thicken and enhance, separated by the infected fluid.'),
    (v_topic_id, '179: "Lung consolidation" moves _____ during respiration.', '["With the lung", "Against the lung", "Not at all", "Randomly"]', 0, 'Since it is part of the lung parenchyma, it moves with the expansion and contraction of the chest.'),
    (v_topic_id, '180: "Mediastinal lymphadenopathy" is considered significant if the nodes are greater than _____ in their short axis.', '["5 mm", "10 mm", "20 mm", "30 mm"]', 1, '1 cm is the standard threshold for "enlarged" nodes on CT.'),
    (v_topic_id, '181: "Anterior Mediastinal" masses (the 4 T''s) include:', '["Thymoma, Thyroid (Retrosternal), Teratoma, Terrible Lymphoma", "Trachea, Thoracic duct, Thyroid, Tumor", "Thymus, T-cells, Trauma, Tobacco", "None of the above"]', 0, 'These arise in the space between the sternum and the heart/great vessels.'),
    (v_topic_id, '182: A "Thyroid mass" in the anterior mediastinum often causes:', '["Tracheal deviation", "Lung collapse", "Rib erosion", "Pleural effusion"]', 0, 'Goiters often extend into the chest and displace the trachea.'),
    (v_topic_id, '183: "Middle Mediastinal" masses commonly include:', '["Neurogenic tumors", "Lymphadenopathy, Bronchogenic cysts, and Pericardial cysts", "Thymomas", "Goiters"]', 1, 'The middle mediastinum contains the hila, heart, and great vessels.'),
    (v_topic_id, '184: "Posterior Mediastinal" masses are most commonly:', '["Lymphomas", "Neurogenic tumors (arising from nerve roots or sympathetic chain)", "Thymomas", "Teratomas"]', 1, 'The "Paravertebral" space is the classic location for these.'),
    (v_topic_id, '185: "Dumbbell tumor" refers to a neurogenic tumor that:', '["Has two lobes", "Extends from the mediastinum through an intervertebral foramen into the spinal canal", "Is very large", "Is benign"]', 1, 'This is a classic description for a schwannoma or neurofibroma.'),
    (v_topic_id, '186: "Pericardial Fat Pad" is a normal finding at the cardiophrenic angle. It can be mistaken for:', '["Lung cancer", "Pleural effusion or a Pericardial cyst", "Heart failure", "Pneumonia"]', 1, 'It appears as a low-density (darker than heart, lighter than air) area at the corner of the heart.'),
    (v_topic_id, '187: "Azygos Lobe" is a common normal variant caused by:', '["A tumor", "The azygos vein tracking through the right upper lobe lung tissue", "A missing rib", "Heart failure"]', 1, 'The "Azygos Fissure" has a characteristic comma-shaped appearance at its lower end.'),
    (v_topic_id, '188: "Pectus Excavatum" (sunken chest) can cause which misleading finding on CXR?', '["Apparent cardiomegaly and blurring of the right heart border", "Lung nodules", "Rib fractures", "Pneumothorax"]', 0, 'The heart is compressed and shifted to the left, mimicking the silhouette sign of RML pneumonia.'),
    (v_topic_id, '189: "Scapula" edges can be mistaken for a:', '["Lung mass", "Pneumothorax line", "Pleural effusion", "Rib fracture"]', 1, 'This is common if the scapulae are not fully protracted out of the lung fields during the PA view.'),
    (v_topic_id, '190: "Nipple shadows" are a classic "pseudo-nodule." How can they be confirmed?', '["Repeat CXR with nipple markers", "Order a CT", "Ask the patient", "Assume they are nodules"]', 0, 'Markers prove that the "nodules" are external soft tissue.'),
    (v_topic_id, '191: "Companion shadows" are thin parallel lines along the top of the ribs or clavicles. They represent:', '["Rib fractures", "Normal soft tissues (skin and muscle) seen in profile", "Pleural thickening", "Pneumothorax"]', 1, 'They are a normal radiographic finding.'),
    (v_topic_id, '192: A "Small Bowel Obstruction" (SBO) on an abdominal film is characterized by:', '["Dilated loops of small bowel (> 3 cm) and multiple air-fluid levels", "Air in the rectum", "A coffee-bean shape", "Dense white stool"]', 0, 'The absence of air in the colon/rectum further supports a complete obstruction.'),
    (v_topic_id, '193: "String of Pearls" sign on an abdominal film refers to:', '["Gallstones", "Small bubbles of air trapped between valvulae conniventes in a fluid-filled obstructed small bowel", "Kidney stones", "Fecaliths"]', 1, 'This is a highly suggestive sign of SBO.'),
    (v_topic_id, '194: "Valvulae Conniventes" (Plicae Circulares) are the mucosal folds of the:', '["Stomach", "Small bowel (they cross the entire width of the lumen)", "Colon", "Esophagus"]', 1, 'This helps distinguish small bowel from colon (which has haustra that do not cross the entire width).'),
    (v_topic_id, '195: "Haustra" are the mucosal folds of the:', '["Small bowel", "Large bowel (they do not cross the entire width)", "Stomach", "Duodenum"]', 1, 'They are spaced further apart than valvulae conniventes.'),
    (v_topic_id, '196: "Paralytic Ileus" differs from a mechanical obstruction because:', '["The bowel is not dilated", "Both the small and large bowel are dilated, and air is present in the rectum", "It is painful", "It requires surgery"]', 1, 'In ileus, there is global dysfunction rather than a single point of blockage.'),
    (v_topic_id, '197: "Sentinel Loop" is a single dilated loop of small bowel near an inflamed organ. It is a classic sign of:', '["Appendicitis", "Acute Pancreatitis", "Cholecystitis", "All of the above"]', 3, 'Localized irritation causes localized paralysis of the bowel.'),
    (v_topic_id, '198: "Pneumobilia" (air in the biliary tree) appears as:', '["Black streaks in the liver region", "Gallstones", "A large mass", "Fluid in the abdomen"]', 0, 'This can be caused by a recent ERCP or a gallstone ileus (fistula between gallbladder and bowel).'),
    (v_topic_id, '199: "Gallstone Ileus" is characterized by the triad of:', '["Fever, Jaundice, Pain", "Small bowel obstruction, Pneumobilia, and an ectopic gallstone", "Ascites, Splenomegaly, Varices", "Pneumothorax, Hemoptysis, Dyspnea"]', 1, 'This is Rigler''s Triad (not to be confused with Rigler''s Sign).'),
    (v_topic_id, '200: "Porcelain Gallbladder" refers to:', '["A gallbladder full of stones", "Extensive calcification of the gallbladder wall", "A perforated gallbladder", "A gallbladder with a tumor"]', 1, 'This is associated with an increased risk of gallbladder carcinoma.');
